package org.opensourcepingpong.competition.algorithm;
import java.util.*;
public final class ScoreValidator {private ScoreValidator(){} public record Game(int a,int b){} public static int winner(Game game){if(Math.max(game.a,game.b)<11||Math.abs(game.a-game.b)<2)throw new IllegalArgumentException("MATCH_INVALID_SCORE");return game.a>game.b?0:1;} public static int matchWinner(int bestOf,List<Game> games){if(bestOf!=3&&bestOf!=5&&bestOf!=7)throw new IllegalArgumentException();int needed=bestOf/2+1,a=0,b=0;for(Game g:games){if(a==needed||b==needed)throw new IllegalArgumentException("extra game");if(winner(g)==0)a++;else b++;}if(a!=needed&&b!=needed)throw new IllegalArgumentException("incomplete");return a>b?0:1;} }
